ruleSearch.coverUrl:
td.0@tag.a@href<js>
var id = result.match(/(\d+)\/?$/)[1];
var iid = parseInt(id/1000);
source.bookSourceUrl + 'files/article/image/'+iid+'/'+id+'/'+id+'s.jpg';
</js>

